export type listRecordsResponse = (listRecordsResponseSuccess | listRecordsResponseError)

export const getListRecordsUrl = (params?: ListRecordsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/records?${stringifiedParams}` : `/api/v1/records`
}

/**
 * @summary Records screen
 */
export const listRecords = async (params?: ListRecordsParams, options?: Parameters<typeof apiFetch>[1]): Promise<listRecordsResponse> => {

  return apiFetch<listRecordsResponse>(getListRecordsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListRecordsQueryKey = (params?: ListRecordsParams,) => {
    return [
    `/api/v1/records`, ...(params ? [params] : [])
    ] as const;
    }


export const getListRecordsQueryOptions = <TData = Awaited<ReturnType<typeof listRecords>>, TError = Problem>(params?: ListRecordsParams, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof listRecords>>, TError, TData>>, request?: SecondParameter<typeof apiFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListRecordsQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listRecords>>> = ({ signal }) => listRecords(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listRecords>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

